"""Continue the native categories chapter without collapsing library differences."""
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'tools'))
from edit_chapter import load,save,transform
paragraphs={
'В half-squared setting можно':'''Для половины квадрата ошибки пример можно проверить без приближения Тейлора. Пусть начальные предсказания равны нулю, а цели — (2,2,−1,−1,1,1,−2,−2). Начальная потеря равна 10. После добавок ±1.2 потеря по данным составляет 1.36, штраф двух листьев — 1.44, всего 2.8. Разница 7.2 совпадает с вычисленным выигрышем. Это точная учебная цель, а не измерение качества LightGBM или XGBoost.''',
'One-category-versus-rest split':'''Проверка одной категории против остальных может выбрать A или D с выигрышем 80/21, но не объединит AC за один шаг. Следующие уровни дерева иногда восстанавливают нужную функцию, затрачивая другую структуру и ёмкость. Преимущество разбиения на подмножества здесь относится к одному узлу и не доказывает невозможности обучения с one-hot.''',
'Наивный algorithm сначала':'''Простой алгоритм сначала суммирует статистики категорий по строкам узла, затем сортирует K значений и проходит по префиксным суммам G/H. Каждую следующую границу после сортировки можно оценить за постоянное время: при переносе категории меняются только соответствующие суммы. Учебная стоимость прохода — O(число строк узла)+O(K log K)+O(K), без экспоненциального перебора. Повторное использование гистограмм, ограничение числа кандидатов, разбиение на интервалы и параллелизм влияют на фактическое время реализации.''',
'Для vector leaf у category':'''Для векторного листа каждой категории соответствует вектор ответа, и одного естественного скалярного порядка нет. Например, (1,2) и (1,−2) имеют одинаковую проекцию на направление (1,0), хотя сильно различаются по второй координате. В [описании XGBoost](https://xgboost.readthedocs.io/en/stable/tutorials/categorical.html) порядок векторных листьев строится по проекции на направление шага Ньютона родительского узла. Это приближение может пропустить различия в ортогональном направлении; поведение при нулевом или слабом родительском направлении нужно проверять в конкретной версии.''',
'LightGBM поддерживает categorical fields':'''LightGBM поддерживает категориальные признаки и разбиение на группы. Метаданные категориальных столбцов в dataframe помогают согласовать категории; для массива сырых чисел правило кодирования нужно сохранять самостоятельно. Отрицательный код категории трактуется как пропуск: общий sentinel unknown=−1 здесь выбирает ветвь пропуска, а не обучает новый эффект неизвестной категории.''',
'Сглаживание и минимальные размеры category groups':'''Сглаживание и минимальный размер групп ограничивают переобучение; эти настройки подбирают внутри проверочной процедуры. При большом числе категорий стоит сравнить встроенную обработку с другими представлениями на одной постановке, не предполагая универсального победителя. См. [официальные правила категорий и пропусков LightGBM](https://lightgbm.readthedocs.io/en/latest/Advanced-Topics.html).''',
'Пример ошибки contract':'''Пример ошибки контракта: при обучении A=0,B=1,C=2, а при применении словарь построили заново как A=0,C=1. Если передать только коды без согласования метаданных, C будет прочитан как B. Совпадение типа и формы массива смысловую ошибку не обнаружит.''',
'CatBoost использует разные numerical statistics':'''CatBoost использует числовые статистики категорий и их сочетаний; небольшие словари в зависимости от режима и настроек могут обрабатываться сравнением с конкретной категорией. Упорядоченные целевые статистики опираются на предшествующие элементы перестановки, а не просто на среднее по всем данным. Ordered boosting отдельно связан со сдвигом предсказаний в самом бустинге. [Описание алгоритма](https://arxiv.org/abs/1706.09516).''',
'Не нужно предварительно one-hot':'''Если требуется встроенная обработка CatBoost, предварительное one-hot кодирование всех полей лишает алгоритм исходных категорий и их сочетаний. Порог такого кодирования и доступные статистики зависят от функции потерь, устройства и настроек. См. [документацию CatBoost](https://catboost.ai/docs/en/features/categorical-features).''',
'Missing marker в string categorical':'''Обозначение пропуска в строковом категориальном поле выбирают явно: строки «1» и «1.0» не обязаны означать одно значение. Представление при обучении и применении должно совпадать; обработку null нельзя механически переносить с числовых признаков. Автоматические сочетания ограничены настройками и вычислительной стоимостью.''',
'XGBoost поддерживает one-hot-подобные':'''XGBoost поддерживает сравнение с одной категорией и разбиение на подмножества; выбор зависит, среди прочего, от `max_cat_to_onehot`. Признаки передают с категориальным типом и включают соответствующую поддержку. Модель сохраняют в формате, который сохраняет категориальные метаданные, например JSON или UBJSON.''',
'Python interface начиная с 3.1':'''Начиная с версии 3.1 Python-интерфейс XGBoost умеет автоматически согласовывать коды категорий для поддерживаемых dataframe. Это помогает сопоставить известные категории, но не создаёт обученной статистики для совершенно новой категории. В других интерфейсах и старых версиях согласование может оставаться задачей предварительной обработки. См. [документацию XGBoost](https://xgboost.readthedocs.io/en/stable/tutorials/categorical.html).''',
'Не следует утверждать исторически':'''Неверно утверждать, что XGBoost вообще не поддерживает встроенные категории; столь же неверно обещать, что новые значения автоматически обрабатываются во всех интерфейсах. Сохранение и загрузку проверяют для конкретного установленного набора библиотек.''',
'В [официальном описании LightGBM]':'''В [описании LightGBM](https://lightgbm.readthedocs.io/en/latest/Advanced-Topics.html) категориальные значения преобразуются в int32, а отрицательные коды означают пропуск. Для dataframe метаданные помогают согласовать словарь. При автоматическом определении упорядоченная категория pandas может обрабатываться как числовая; если нужна именно категориальная обработка, её задают явно. В описанном интерфейсе ранее невиденные значения при прогнозе обрабатываются как пропуск.''',
'Следовательно, перестановка только raw codes':'''Перестановка сырых кодов без сохранённого словаря нарушает смысл входа: одинаковое целое 1 может обозначать разные категории. Отдельно проверяют, является ли 0 допустимой категорией по схеме; он не означает пропуск универсально. Сглаживание стабилизирует оценку, но не восстанавливает смысл после ошибочного перекодирования.''',
'Упрощённый путь такой:':'''Упрощённая последовательность CatBoost: ключ категории или сочетание нескольких полей определяет статистику; статистику строят по разрешённой истории или перестановке; дерево выбирает порог по полученному числу. Для небольших словарей возможно сравнение с одной категорией. Различные виды CTR и режимы не сводятся к одному среднему из [главы о целевых статистиках](<feat-target.md>).''',
'Для нового tuple, даже если':'''Для нового сочетания категорий число наблюдений может быть нулевым, даже если каждый компонент известен. Тогда выбранная статистика использует предусмотренное априорное или резервное значение. Известность компонентов не равна наличию данных об их совместном эффекте. Число сочетаний ограничивают настройки и бюджет; строковые значения приводят к одинаковому виду при обучении и прогнозе.''',
'Документация [CatBoost categorical features]':'''[Документация CatBoost](https://catboost.ai/docs/en/features/categorical-features) указывает зависимость выбора one-hot от режима обучения; для признаков, выбранных этим путём, CTR не вычисляются. Поэтому порог `one_hot_max_size` меняет путь представления, а не только скорость одной и той же функции. Нельзя приписывать одну фиксированную настройку всем функциям потерь и устройствам.''',
'Auto-recoding поддержанных dataframe inputs':'''Автоматическое перекодирование поддерживаемых dataframe сопоставляет сохранённые категории и их коды; интерфейс сырых массивов и старые версии могут требовать собственного словаря. Если в проверочном пакете есть только A/C, локальные коды 0/1 не обязаны совпасть с обучающими A/B/C=0/1/2. Нужно согласовать значения, а не только диапазон кодов.''',
'Истинно новая D отличается':'''Новая категория D отличается от известной B, которая просто отсутствует в текущем пакете. [Документация XGBoost](https://xgboost.readthedocs.io/en/stable/tutorials/categorical.html) отдельно описывает ограничения согласования и новых значений. Файл JSON/UBJSON сохраняет категориальную информацию модели, но схема обработки и разрешённые исходные типы тоже нужны. Один параметр `enable_categorical` не устраняет все несовпадения входов.''',
'У редкой category случайный gradient':'''Для редкой категории случайный градиент может быть большим относительно доступной суммы вторых производных H. При G=1 и H=0.001 нерегуляризованный ответ равен −1000; при λ=1 он примерно −0.999. Пример показывает стабилизацию знаменателя, а не типичность таких величин для любой функции потерь. Градиенты и вторые производные должны соответствовать выбранной цели и весам строк.''',
'Minimum child Hessian, число строк':'''Минимальная сумма вторых производных в дочернем узле, число строк и число категорий в группе — разные ограничения. В логистической потере вторая производная уверенного прогноза намного меньше 0.25, поэтому много строк не гарантирует большой H. Объединение редких категорий и сглаживание меняют порядок кандидатов; настройки выбирают на корректной проверке, а не по выигрышу разбиения на тесте.''',
'Для arbitrary unique IDs training tree':'''Для случайных уникальных ID дерево может запомнить случайные сочетания меток. Встроенная обработка категорий не создаёт повторных наблюдений новых ID. Разбиение должно соответствовать применению: новые объекты, известные объекты в будущем или новые сочетания. Градиенты дерева по обучающим меткам допустимы как часть обучения; использование внешних проверочных меток для подготовки статистик или выбора дерева — утечка.''',
'Одинаковый split и исходные':'''Сравнивайте методы на одинаковых разбиениях и разрешённых признаках, с сопоставимым бюджетом настройки и одной целевой метрикой; отдельно сообщайте память и задержку. Встроенную обработку полезно сопоставить с one-hot, частотой или корректной OOF-кодировкой. Одинаковое число деревьев само по себе не означает одинаковых вычислений и ёмкости.''',
'Обязательно сохраняем pipeline':'''Сохраните конвейер, загрузите его и сравните предсказания для известных, редких, пропущенных и новых значений, а также при изменённом порядке словаря. Проверьте известную категорию, которая просто отсутствует в текущем пакете: это другой случай, чем новая категория. В артефакте фиксируют состояние словаря и резервное поведение.''',
'Сравнивают прежде всего validation predictions':'''Сравнивают прогнозы на одних и тех же разрешённых проверочных объектах. Одинаковый `n_estimators` не выравнивает глубину и число листьев, раннюю остановку, оборудование или стоимость подбора. Отдельно фиксируют построение признаков, обучение, размер файла и путь применения; общую метрику дополняют срезами известных частых и редких значений, новых сочетаний, новых категорий и пропусков.''',
'В воспроизводимом artifact нужны':'''Для воспроизводимости нужны правила приведения категорий, имена и порядок колонок, объявленные категориальные поля, словарь и метаданные, формат модели, версия, устройство, настройки, временная граница и правило неизвестного значения. Для проверки после загрузки сохраняют небольшой набор сырых входов и исходные прогнозы, затем сравнивают результаты с заявленной точностью и проверяют фактическое резервное поведение. Один известный вход не покрывает новые значения и пропуски.'''
}
def op(t):
 for prefix,new in paragraphs.items():
  a=t.find(prefix)
  if a<0:raise ValueError('Missing paragraph: '+prefix)
  ends=[i for i in (t.find('\n\n',a),t.find('\n<!-- EDIT:',a),t.find('\n<!-- /EDIT:',a)) if i>=0]
  if not ends:raise ValueError('Missing boundary: '+prefix)
  b=min(ends);t=t[:a]+new+t[b:]
 return t
c=load();transform('01-data-features/02-features/feat-native.md',op,
 'Пакет 03: редактура различий библиотек и воспроизводимого контракта; примеры и оговорки сохранены, приёмка ожидается.',c);save(c)
print('Native split and library contracts edited; review remains open.')
